['invest_sum'] !== '')?$vo['invest_sum']:'--')); ?> 元</a><br></td><td class='text-left nowrap'>                待收利息：<?php echo htmlentities((isset($vo['wait_invest']) && ($vo['wait_invest'] !== '')?$vo['wait_invest']:'--')); ?> 元<br>                待收本金：<?php echo htmlentities((isset($vo['wait_money']) && ($vo['wait_money'] !== '')?$vo['wait_money']:'--')); ?> 元<br>                成长值：<?php echo htmlentities((isset($vo['value']) && ($vo['value'] !== '')?$vo['value']:'--')); ?><br></td><td class='text-left nowrap'>                用户状态：
