a-action="<?php echo url(ADMIN_MODULE.'/users/setrobot'); ?>" data-value="id#<?php echo htmlentities($vo['id']); ?>;clock#<?php echo $vo['robot']==1 ? 0 : 1; ?>" data-csrf="<?php echo systoken('setrobot'); ?>"><?php echo $vo['robot']==1 ? "设置成真人" : "设置成假人"; ?></a><a style="margin-top:5px" data-dbclick class="layui-btn layui-btn-sm layui-btn-success" data-title="充值" data-modal='<?php echo url(ADMIN_MODULE."/users/operationMoney"); ?>?id=<?php echo htmlentities($vo['id']); ?>&type=0'>充值</a><a style="margin-top:5px" data-dbclick class="layui-btn layui-btn-sm layui-btn-danger" data-title="扣款" data-modal='<?php echo url(ADMIN_MODULE."/users/operationMoney"); ?>?id=<?php echo htmlentities($vo['id']); ?>&type=1'>扣款</a></td></tr><?php endforeach; ?></tbody></table><?php if(empty($list) || (($list instanceof \think\Collection || $list instanceof \think\Paginator ) && $list->isEmpty())): ?><span class="notdata">没有记录哦</span><?php else: ?><?php echo (isset($pagehtml) && ($pagehtml !== '')?$pagehtml:''); ?><?php endif; ?></div></div></div>